const table=document.createElement("table");table.className="typing-result";table.id="ty-result";for(const [k,v] of rows){const tr_=table.insertRow();tr_.insertCell().textContent=k;tr_.insertCell().textContent=String(v);}result.append(table);
if(r.samples.length){const h=document.createElement("h3");h.textContent=hindi?"गलत शब्द":"Words to check";const ul=document.createElement("ul");ul.className="checklist";for(const x of r.samples.slice(0,15)){const li=document.createElement("li");li.textContent=x.expected?(hindi?`आपने “${x.typed}” लिखा, सही: “${x.expected}”`:`You typed “${x.typed}”, expected “${x.expected}”`):(hindi?`अतिरिक्त: “${x.typed}”`:`Extra: “${x.typed}”`);ul.append(li);}result.append(h,ul);}
