async function photoSheet(){
const paper=$("paper").value,count=Number($("copies").value),ratio=$("frame-ratio").value,border=$("frame-border").value==="yes";
if(!["a4","4x6"].includes(paper)||![4,6,8,12].includes(count)||!["3:4","1:1","2:3","4:3"].includes(ratio))fail("Invalid photo sheet settings.");
const im=await load($("files").files[0]);let sheet,frame;try{
const [w,h]=paper==="a4"?[2480,3508]:[1200,1800], [a,b]=ratio.split(":").map(Number),margin=paper==="a4"?100:48,gap=paper==="a4"?50:24;
let best=null;for(let cols=1;cols<=count;cols++){const rows=Math.ceil(count/cols),scale=Math.floor(Math.min((w-2*margin-(cols-1)*gap)/cols/a,(h-2*margin-(rows-1)*gap)/rows/b));if(scale>0&&(!best||scale>best.scale))best={cols,rows,scale};}
if(!best)fail("Invalid frame layout.");const fw=best.scale*a,fh=best.scale*b;frame=draw(im,fw,fh,"crop");sheet=canvas(w,h);const ctx=sheet.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,w,h);
const top=Math.floor((h-best.rows*fh-(best.rows-1)*gap)/2);
for(let i=0;i<count;i++){const row=Math.floor(i/best.cols),col=i%best.cols,items=Math.min(best.cols,count-row*best.cols),left=Math.floor((w-items*fw-(items-1)*gap)/2),x=left+col*(fw+gap),y=top+row*(fh+gap);ctx.drawImage(frame,x,y);if(border){ctx.strokeStyle="#667085";ctx.lineWidth=2;ctx.strokeRect(x+1,y+1,fw-2,fh-2);}if(i%4===3)await breathe();}
const blob=await jpeg(sheet,.92);download(blob,"kaagazkit-photo-sheet.jpg",true);paragraph((hindi?count+" फोटो · ":count+" photos · ")+w+" × "+h+" pixels");paragraph((hindi?"फ्रेम: ":"Frame: ")+fw+" × "+fh+" pixels");paragraph(hindi?"प्रिंट में चुना गया पेपर आकार सेट करें। आधिकारिक फोटो मानक जांचें।":"Set the chosen paper size when printing. Verify official photo requirements.");
}finally{im.close();if(frame)frame.width=frame.height=1;if(sheet)sheet.width=sheet.height=1;}}
async function makeQr(){if(typeof globalThis.qrcode!=="function")fail("QR engine unavailable. Reload and try again.");const value=$("qr-text").value;if(!value.trim()||new TextEncoder().encode(value).length>500)fail("Enter 1–500 UTF-8 bytes.");qrcode.stringToBytes=s=>Array.from(new TextEncoder().encode(s));const qr=qrcode(0,"M");qr.addData(value,"Byte");qr.make();const count=qr.getModuleCount(),scale=10,quiet=4,c=canvas((count+quiet*2)*scale,(count+quiet*2)*scale),ctx=c.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle="#000";for(let y=0;y<count;y++)for(let x=0;x<count;x++)if(qr.isDark(y,x))ctx.fillRect((x+quiet)*scale,(y+quiet)*scale,scale,scale);const b=await encode(c,"image/png");download(b,"kaagazkit-qr.png",true);paragraph("Scan to verify before sharing. QR code contains the input text.");c.width=c.height=1;}
